import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import Header from './Header'
import Sidebar from './Sidebar'
import StatCard from './StatCard'
import RecentProjects from './RecentProjects'
import RecentActivity from './RecentActivity'
import QuickActions from './QuickActions'
import PerformanceChart from './PerformanceChart'
import Messages from './Messages'
import Settings from './Settings'
import { 
  Folder, 
  CheckCircle, 
  Users, 
  DollarSign,
  TrendingUp,
  Clock,
  Award,
  Target
} from 'lucide-react'

const Dashboard = () => {
  const [user, setUser] = useState(null)
  const [dashboardData, setDashboardData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [sidebarOpen, setSidebarOpen] = useState(false)
  const [activeTab, setActiveTab] = useState('overview')
  const navigate = useNavigate()

  useEffect(() => {
    const token = localStorage.getItem('token')
    const userData = localStorage.getItem('user')

    if (!token || !userData) {
      navigate('/')
      return
    }

    setUser(JSON.parse(userData))
    fetchDashboardData()
  }, [navigate])

  const fetchDashboardData = async () => {
    try {
      const token = localStorage.getItem('token')
      const response = await fetch('http://localhost:5000/api/users/dashboard', {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      })

      if (response.ok) {
        const data = await response.json()
        setDashboardData(data.data)
      } else {
        setDashboardData(getMockData())
      }
    } catch (error) {
      console.error('Erreur de connexion:', error)
      setDashboardData(getMockData())
    } finally {
      setLoading(false)
    }
  }

  const getMockData = () => {
    return {
      stats: {
        totalProjects: 12,
        completedProjects: 8,
        pendingTasks: 5,
        revenue: 12500,
        growth: 15.3,
        customers: 245,
        revenueChange: 15.3,
        projectChange: 12,
        customerChange: 5.2,
        taskChange: 8
      },
      recentActivity: [
        {
          id: 1,
          action: 'Projet créé',
          description: 'Nouveau site e-commerce',
          time: 'Il y a 2 heures',
          type: 'project',
          icon: '📁',
          color: 'bg-blue-500'
        },
        {
          id: 2,
          action: 'Tâche terminée',
          description: 'Design de la homepage',
          time: 'Il y a 1 jour',
          type: 'task',
          icon: '✅',
          color: 'bg-green-500'
        },
        {
          id: 3,
          action: 'Client ajouté',
          description: 'Nouveau contrat signé',
          time: 'Il y a 3 heures',
          type: 'client',
          icon: '👥',
          color: 'bg-purple-500'
        },
        {
          id: 4,
          action: 'Facture envoyée',
          description: 'Projet #2456',
          time: 'Il y a 5 heures',
          type: 'invoice',
          icon: '💰',
          color: 'bg-yellow-500'
        }
      ],
      projects: [
        {
          id: 1,
          name: 'Site E-commerce',
          progress: 80,
          status: 'in_progress',
          deadline: '2024-03-30',
          team: 3,
          budget: 15000,
          color: 'bg-gradient-to-r from-blue-500 to-cyan-500'
        },
        {
          id: 2,
          name: 'Application Mobile',
          progress: 45,
          status: 'in_progress',
          deadline: '2024-05-15',
          team: 2,
          budget: 20000,
          color: 'bg-gradient-to-r from-purple-500 to-pink-500'
        },
        {
          id: 3,
          name: 'Dashboard Admin',
          progress: 100,
          status: 'completed',
          deadline: '2024-02-20',
          team: 4,
          budget: 12000,
          color: 'bg-gradient-to-r from-green-500 to-emerald-500'
        },
        {
          id: 4,
          name: 'API Backend',
          progress: 30,
          status: 'pending',
          deadline: '2024-06-10',
          team: 2,
          budget: 8000,
          color: 'bg-gradient-to-r from-orange-500 to-red-500'
        }
      ],
      chartData: {
        labels: ['Jan', 'Fév', 'Mar', 'Avr', 'Mai', 'Jun'],
        revenue: [12000, 19000, 15000, 25000, 22000, 30000],
        projects: [4, 6, 5, 8, 7, 10]
      },
      quickStats: {
        efficiency: 78,
        onTime: 92,
        satisfaction: 4.8
      }
    }
  }

  const renderContent = () => {
    // Vérifier si dashboardData est défini
    if (!dashboardData) {
      return (
        <div className="flex items-center justify-center py-20">
          <div className="text-center">
            <div className="w-16 h-16 border-4 border-gray-300 rounded-full animate-spin border-t-blue-500 mx-auto"></div>
            <p className="mt-4 text-gray-600">Chargement des données...</p>
          </div>
        </div>
      )
    }

    switch (activeTab) {
      case 'overview':
        return (
          <>
            {/* Welcome Section with Stats */}
            <div className="mb-8">
              <div className="flex flex-col md:flex-row md:items-center justify-between mb-6">
                <div>
                  <h1 className="text-3xl font-bold text-gray-900 mb-2">
                    Bonjour, <span className="bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">
                      {user?.first_name} 👋
                    </span>
                  </h1>
                  <p className="text-gray-600">
                    Voici votre tableau de bord pour aujourd'hui
                  </p>
                </div>
                <div className="mt-4 md:mt-0 flex items-center space-x-3">
                  <div className="px-4 py-2 bg-gradient-to-r from-blue-50 to-blue-100 rounded-xl border border-blue-200">
                    <p className="text-sm text-blue-700">
                      <span className="font-semibold">📅 {new Date().toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long' })}</span>
                    </p>
                  </div>
                  <button className="px-4 py-2 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-xl hover:shadow-lg hover:shadow-blue-500/25 transition-all duration-300 flex items-center space-x-2">
                    <TrendingUp size={16} />
                    <span>Générer Rapport</span>
                  </button>
                </div>
              </div>

              {/* Stats Grid */}
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                <StatCard
                  icon={Folder}
                  title="Projets Totaux"
                  value={dashboardData?.stats?.totalProjects || 0}
                  change={dashboardData?.stats?.projectChange || 0}
                  color="from-blue-500 to-cyan-500"
                  gradient={true}
                />
                <StatCard
                  icon={CheckCircle}
                  title="Projets Terminés"
                  value={dashboardData?.stats?.completedProjects || 0}
                  change={dashboardData?.stats?.taskChange || 0}
                  color="from-green-500 to-emerald-500"
                  gradient={true}
                />
                <StatCard
                  icon={Users}
                  title="Clients Actifs"
                  value={dashboardData?.stats?.customers || 0}
                  change={dashboardData?.stats?.customerChange || 0}
                  color="from-purple-500 to-pink-500"
                  gradient={true}
                />
                <StatCard
                  icon={DollarSign}
                  title="Revenu Total"
                  value={`${(dashboardData?.stats?.revenue || 0).toLocaleString()} €`}
                  change={dashboardData?.stats?.revenueChange || 0}
                  color="from-yellow-500 to-orange-500"
                  gradient={true}
                />
              </div>

              {/* Quick Stats */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                <div className="bg-gradient-to-r from-indigo-500 to-purple-600 rounded-2xl p-6 text-white">
                  <div className="flex items-center justify-between mb-4">
                    <div>
                      <p className="text-sm opacity-90">Efficacité</p>
                      <p className="text-3xl font-bold">{dashboardData?.quickStats?.efficiency || 0}%</p>
                    </div>
                    <div className="w-14 h-14 bg-white/20 rounded-full flex items-center justify-center">
                      <Target className="w-7 h-7" />
                    </div>
                  </div>
                  <div className="w-full bg-white/20 rounded-full h-2">
                    <div 
                      className="bg-white h-2 rounded-full transition-all duration-1000 ease-out"
                      style={{ width: `${dashboardData?.quickStats?.efficiency || 0}%` }}
                    ></div>
                  </div>
                </div>

                <div className="bg-gradient-to-r from-blue-500 to-cyan-500 rounded-2xl p-6 text-white">
                  <div className="flex items-center justify-between mb-4">
                    <div>
                      <p className="text-sm opacity-90">À Temps</p>
                      <p className="text-3xl font-bold">{dashboardData?.quickStats?.onTime || 0}%</p>
                    </div>
                    <div className="w-14 h-14 bg-white/20 rounded-full flex items-center justify-center">
                      <Clock className="w-7 h-7" />
                    </div>
                  </div>
                  <div className="w-full bg-white/20 rounded-full h-2">
                    <div 
                      className="bg-white h-2 rounded-full transition-all duration-1000 ease-out"
                      style={{ width: `${dashboardData?.quickStats?.onTime || 0}%` }}
                    ></div>
                  </div>
                </div>

                <div className="bg-gradient-to-r from-green-500 to-emerald-600 rounded-2xl p-6 text-white">
                  <div className="flex items-center justify-between mb-4">
                    <div>
                      <p className="text-sm opacity-90">Satisfaction</p>
                      <p className="text-3xl font-bold">{dashboardData?.quickStats?.satisfaction || 0}/5</p>
                    </div>
                    <div className="w-14 h-14 bg-white/20 rounded-full flex items-center justify-center">
                      <Award className="w-7 h-7" />
                    </div>
                  </div>
                  <div className="flex space-x-1">
                    {[...Array(5)].map((_, i) => (
                      <div
                        key={i}
                        className={`flex-1 h-2 rounded-full ${
                          i < Math.floor(dashboardData?.quickStats?.satisfaction || 0) 
                            ? 'bg-white' 
                            : 'bg-white/20'
                        }`}
                      ></div>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            {/* Main Content Grid */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              <div className="lg:col-span-2 space-y-6">
                <RecentProjects projects={dashboardData?.projects || []} />
                <PerformanceChart data={dashboardData?.chartData} />
              </div>
              <div className="space-y-6">
                <RecentActivity activities={dashboardData?.recentActivity || []} />
                <QuickActions />
              </div>
            </div>
          </>
        )

      case 'messages':
        return <Messages user={user} />

      case 'settings':
        return <Settings user={user} />

      case 'projects':
        return (
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <div>
                <h1 className="text-3xl font-bold text-gray-900 mb-2">Mes Projets</h1>
                <p className="text-gray-600">Gérez tous vos projets en un seul endroit</p>
              </div>
              <button className="px-4 py-2 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-xl hover:shadow-lg hover:shadow-blue-500/25 transition-all duration-300">
                + Nouveau Projet
              </button>
            </div>
            <RecentProjects projects={dashboardData?.projects || []} showAll={true} />
          </div>
        )

      case 'tasks':
        return (
          <div className="space-y-6">
            <div className="flex items-center justify-between">
              <div>
                <h1 className="text-3xl font-bold text-gray-900 mb-2">Mes Tâches</h1>
                <p className="text-gray-600">Suivez l'avancement de vos tâches</p>
              </div>
              <button className="px-4 py-2 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-xl hover:shadow-lg hover:shadow-blue-500/25 transition-all duration-300">
                + Nouvelle Tâche
              </button>
            </div>
            <div className="bg-white rounded-2xl shadow-lg p-6 border border-gray-100">
              <p className="text-gray-600 text-center py-8">
                Interface des tâches en cours de développement...
              </p>
            </div>
          </div>
        )

      default:
        return (
          <div className="space-y-6">
            <h1 className="text-3xl font-bold text-gray-900 mb-6">
              {activeTab.charAt(0).toUpperCase() + activeTab.slice(1)}
            </h1>
            <div className="bg-white rounded-2xl shadow-lg p-6 border border-gray-100">
              <p className="text-gray-600 text-center py-8">
                Page en cours de développement...
              </p>
            </div>
          </div>
        )
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-gray-50 to-gray-100">
        <div className="text-center space-y-4">
          <div className="relative">
            <div className="w-16 h-16 border-4 border-blue-200 rounded-full animate-spin"></div>
            <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-8 h-8 bg-gradient-to-r from-blue-600 to-purple-600 rounded-full"></div>
          </div>
          <div>
            <p className="text-gray-700 font-medium">Chargement du dashboard...</p>
            <p className="text-sm text-gray-500 mt-1">Préparation de votre espace de travail</p>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 via-gray-50 to-blue-50/20 flex">
      <Sidebar 
        isOpen={sidebarOpen} 
        onClose={() => setSidebarOpen(false)}
        activeTab={activeTab}
        onTabChange={setActiveTab}
        user={user}
      />

      <div className="flex-1 flex flex-col lg:ml-64 transition-all duration-300">
        <Header 
          user={user}
          onMenuClick={() => setSidebarOpen(true)}
          onSearch={(query) => console.log('Search:', query)}
          currentPage={activeTab}
        />

        <main className="flex-1 p-6 md:p-8">
          <div className="max-w-7xl mx-auto">
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  )
}

export default Dashboard
